#!/usr/bin/env python3
"""Probe a krun/Podman microVM from the inside and emit /app/report.json."""
import json
import os
import re
import signal
import socket
import subprocess
import sys

REPORT_PATH = "/app/report.json"

# Candidate container-engine control socket paths.
CANDIDATE_SOCKETS = [
    "/var/run/docker.sock",
    "/run/docker.sock",
    "/run/podman/podman.sock",
    "/var/run/podman/podman.sock",
    "/run/crio/crio.sock",
    "/run/containerd/containerd.sock",
    "/run/k3s/containerd/containerd.sock",
    "/run/buildkit/buildkitd.sock",
]
ENGINE_SOCK_BASENAMES = {
    "docker.sock", "podman.sock", "crio.sock", "containerd.sock", "buildkitd.sock",
}


class _Timeout(Exception):
    pass


def _alarm(signum, frame):
    raise _Timeout("probe timed out")


def with_timeout(seconds, fn, *args, **kwargs):
    """Run fn with a SIGALRM-based timeout (main thread only)."""
    old = signal.signal(signal.SIGALRM, _alarm)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        return fn(*args, **kwargs)
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, old)


# ---------------------------------------------------------------- individual probes
def probe_dns():
    """Name resolution only (no TCP connection)."""
    infos = with_timeout(8, socket.getaddrinfo, "example.com", 443,
                         socket.AF_UNSPEC, socket.SOCK_STREAM)
    return bool(infos)


def probe_http():
    """Full HTTPS fetch; must complete with a successful curl exit code."""
    proc = subprocess.run(
        [
            "curl", "-sS", "-o", "/dev/null",
            "--max-time", "12", "--connect-timeout", "8",
            "-w", "%{http_code}",
            "https://example.com",
        ],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=20,
    )
    code = proc.stdout.decode("utf-8", "replace").strip()
    return proc.returncode == 0 and code.startswith("2")


def probe_uid():
    return int(os.getuid())


def probe_engine_sockets():
    found = set()
    for path in CANDIDATE_SOCKETS:
        try:
            if os.path.exists(path):
                found.add(path)
        except OSError:
            pass
    # Also catch anything engine-like that may live elsewhere under /run.
    for root in ("/run", "/var/run"):
        for dirpath, _dirnames, filenames in os.walk(root):
            for name in filenames:
                if name in ENGINE_SOCK_BASENAMES:
                    found.add(os.path.join(dirpath, name))
    return sorted(found)


def _probe_writable(directory):
    path = os.path.join(directory, ".writable_probe")
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            os.write(fd, b"probe")
            os.fsync(fd)
        finally:
            os.close(fd)
        os.unlink(path)
        return True
    except OSError:
        try:
            if os.path.exists(path):
                os.unlink(path)
        except OSError:
            pass
        return False


def probe_writable_workdir():
    return _probe_writable("/app")


def probe_writable_tmp():
    return _probe_writable("/tmp")


def probe_net_interfaces():
    return sorted(os.listdir("/sys/class/net"))


def probe_cpu_hypervisor():
    with open("/proc/cpuinfo", "r") as fh:
        for line in fh:
            if line.lower().startswith("flags"):
                tokens = line.split(":", 1)[1].split()
                if "hypervisor" in tokens:
                    return True
    return False


def probe_vsock_dev():
    return os.path.exists("/dev/vsock")


def probe_sysrq_writable():
    """Actually attempt to write 'h' and close the file so errors surface."""
    fd = os.open("/proc/sysrq-trigger", os.O_WRONLY)
    try:
        os.write(fd, b"h")
        os.fsync(fd)
    finally:
        os.close(fd)
    return True


def probe_nproc():
    proc = subprocess.run(["nproc"], stdout=subprocess.PIPE,
                          stderr=subprocess.DEVNULL, timeout=5)
    return int(proc.stdout.decode().strip())


def probe_mem_total_kb():
    with open("/proc/meminfo", "r") as fh:
        for line in fh:
            if line.startswith("MemTotal:"):
                m = re.search(r"(\d+)", line)
                if m:
                    return int(m.group(1))
    raise ValueError("MemTotal not found")


def probe_pid1_comm():
    with open("/proc/1/comm", "r") as fh:
        return fh.read().strip()


def probe_kernel_release():
    return os.uname().release.strip()


# Boolean probes get False on any failure (including timeout/quota errors).
PROBES = [
    ("egress_http", probe_http, "bool"),
    ("dns", probe_dns, "bool"),
    ("uid", probe_uid, "any"),
    ("engine_sockets", probe_engine_sockets, "list"),
    ("writable_workdir", probe_writable_workdir, "bool"),
    ("writable_tmp", probe_writable_tmp, "bool"),
    ("net_interfaces", probe_net_interfaces, "list"),
    ("cpu_hypervisor", probe_cpu_hypervisor, "bool"),
    ("vsock_dev", probe_vsock_dev, "bool"),
    ("sysrq_writable", probe_sysrq_writable, "bool"),
    ("nproc", probe_nproc, "any"),
    ("mem_total_kb", probe_mem_total_kb, "any"),
    ("pid1_comm", probe_pid1_comm, "str"),
    ("kernel_release", probe_kernel_release, "str"),
]


def main():
    report = {}
    for key, fn, kind in PROBES:
        try:
            value = fn()
        except Exception as exc:  # treat errors as data, never abort
            sys.stderr.write("probe %s failed: %r\n" % (key, exc))
            if kind == "bool":
                value = False
            elif kind == "list":
                value = []
            elif kind == "str":
                value = ""
            else:
                value = None
        report[key] = value

    # Ensure JSON-serialisable and stable ordering.
    with open(REPORT_PATH, "w") as fh:
        json.dump(report, fh, indent=2, sort_keys=False)
        fh.write("\n")

    print(json.dumps(report, indent=2, sort_keys=False))


if __name__ == "__main__":
    main()
PYEOF
echo "script written"; python3 /tmp/probe.py
